approvals.description:
Execute JavaScript code against the Cloudflare API. Write an async arrow function; it runs in an isolated Worker with a `cloudflare` client bound to the signed-in account. Use `search` first to find the endpoint you need.

Available in scope:
- `cloudflare.request({ method, path, query?, body?, headers? })` returns the parsed JSON envelope `{ success, errors, messages, result, result_info }`.
- `accountId`: the account you signed in to.

Paths are relative to https://api.cloudflare.com/client/v4. Pagination: pass `query: { page, per_page }` and read `result_info.total_pages`.

Example: List zones:
async () => {
  const zones = await cloudflare.request({ method: "GET", path: "/zones", query: { per_page: 50 } });
  return zones.result.map(z => ({ id: z.id, name: z.name, status: z.status }));
}

Example: Create a DNS record:
async () => {
  return cloudflare.request({ method: "POST", path: `/zones/${zoneId}/dns_records`, body: { type: "A", name: "www", content: "192.0.2.1", proxied: true } });
}

Example: Purge cache:
async () => {
  return cloudflare.request({ method: "POST", path: `/zones/${zoneId}/purge_cache`, body: { purge_everything: true } });
}

Example: Worker with bindings (a multipart/form-data upload):
async () => {
  const code = `export default { async fetch(request, env) { return new Response(await env.MY_KV.get('key') || 'none') } };`;
  const metadata = { main_module: "worker.js", bindings: [{ type: "kv_namespace", name: "MY_KV", namespace_id: "your-kv-id" }] };
  const form = new FormData();
  form.append("metadata", new Blob([JSON.stringify(metadata)], { type: "application/json" }));
  form.append("worker.js", new Blob([code], { type: "application/javascript+module" }), "worker.js");
  return cloudflare.request({ method: "PUT", path: `/accounts/${accountId}/workers/scripts/my-worker`, body: form });
}

input.code:
async () => {
  const out = {};
  const zones = (await cloudflare.request({ method: "GET", path: "/zones", query: { per_page: 50 } })).result;
  const ids = ["ssl","min_tls_version","always_use_https","security_header","tls_1_3","automatic_https_rewrites","waf","security_level"];
  for (const z of zones) {
    const s = {};
    try {
      const all = (await cloudflare.request({ method: "GET", path: `/zones/${z.id}/settings` })).result;
      for (const x of all) if (ids.includes(x.id)) s[x.id] = x.value;
    } catch (e) { s.error = String(e).slice(0, 200); }
    try {
      const rs = await cloudflare.request({ method: "GET", path: `/zones/${z.id}/rulesets` });
      s.rulesets = rs.result.map(r => ({ id: r.id, phase: r.phase, kind: r.kind, name: r.name }));
    } catch (e) { s.rulesets_error = String(e).slice(0, 200); }
    try {
      const dns = await cloudflare.request({ method: "GET", path: `/zones/${z.id}/dns_records`, query: { per_page: 100 } });
      s.unproxied = dns.result.filter(r => ["A","AAAA","CNAME"].includes(r.type) && !r.proxied).map(r => `${r.type} ${r.name} ${r.content}`);
    } catch (e) { s.dns_error = String(e).slice(0, 200); }
    out[z.name] = s;
  }
  return out;
}
